import { useEffect, useState } from 'react'
import { useAuth } from '@/features/auth'
import { deleteMenuItem, getVendorId, getVendorMenu, saveVendorMenuItem, setMenuAvailability, uploadMenuImage, type VendorMenuItem } from '../api/vendorDashboard.api'
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/components/ui/card'
import { Button } from '@/shared/components/ui/button'
import { Input } from '@/shared/components/ui/input'
import { Textarea } from '@/shared/components/ui/textarea'
import { Switch } from '@/shared/components/ui/switch'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/shared/components/ui/dialog'
import { formatNaira } from '@/shared/lib/currency'
import { toast } from 'sonner'
type Draft = { id?: string; name: string; description: string; price: string; category: string; image?: File; imageUrl?: string | null }
const empty: Draft = { name: '', description: '', price: '', category: '' }
export function Component() { const user = useAuth((s) => s.user); const [vendorId, setVendorId] = useState<string>(); const [items, setItems] = useState<VendorMenuItem[]>([]); const [draft, setDraft] = useState<Draft>(); const [saving, setSaving] = useState(false); const [deleting, setDeleting] = useState<VendorMenuItem>()
  const load = async () => { if (!user) return; const id = await getVendorId(user.id); if (id) { setVendorId(id); setItems(await getVendorMenu(id)) } }; useEffect(() => { void load() }, [user])
  const toggle = async (item: VendorMenuItem, available: boolean) => { setItems((all) => all.map((row) => row.id === item.id ? { ...row, available } : row)); try { await setMenuAvailability(item.id, available); toast.success('Availability updated.') } catch (error) { setItems((all) => all.map((row) => row.id === item.id ? item : row)); toast.error(error instanceof Error ? error.message : 'Unable to update item.') } }
  const save = async () => { if (!draft || !vendorId) return; const price = Number(draft.price); if (!draft.name.trim() || !Number.isFinite(price) || price <= 0) return toast.error('Enter a name and a positive price.'); setSaving(true); try { const imageUrl = draft.image ? await uploadMenuImage(vendorId, draft.image) : draft.imageUrl; await saveVendorMenuItem(vendorId, { id: draft.id, name: draft.name.trim(), description: draft.description, price, category: draft.category, imageUrl }); toast.success(draft.id ? 'Menu item updated.' : 'Menu item added.'); setDraft(undefined); await load() } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save menu item.') } finally { setSaving(false) } }
  const remove = async () => { if (!deleting) return; try { await deleteMenuItem(deleting.id); toast.success('Menu item deleted.'); setDeleting(undefined); await load() } catch (error) { toast.error('This item has past orders and cannot be deleted — mark it unavailable instead.') } }
  return <div className="space-y-6"><div className="flex items-end justify-between"><div><h1 className="text-3xl font-semibold">Menu management</h1><p className="text-muted-foreground">Control which dishes customers can order.</p></div><Button onClick={() => setDraft(empty)}>Add menu item</Button></div><Card><CardHeader><CardTitle>Your menu</CardTitle></CardHeader><CardContent className="space-y-3">{items.map((item) => <div key={item.id} className="flex items-center gap-4 rounded-lg border p-3"><div className="size-14 overflow-hidden rounded bg-muted">{item.imageUrl && <img src={item.imageUrl} className="size-full object-cover" />}</div><div className="min-w-0 flex-1"><p className="font-medium">{item.name}</p><p className="text-sm text-muted-foreground">{item.category && `${item.category} · `}{formatNaira(item.price * 100)}</p></div><Switch checked={item.available} onCheckedChange={(available) => void toggle(item, available)} aria-label={`Set ${item.name} availability`} /><Button variant="outline" size="sm" onClick={() => setDraft({ id: item.id, name: item.name, description: item.description ?? '', price: String(item.price), category: item.category ?? '', imageUrl: item.imageUrl })}>Edit</Button><Button variant="destructive" size="sm" onClick={() => setDeleting(item)}>Delete</Button></div>)}{!items.length && <p className="py-8 text-center text-muted-foreground">You haven't added any menu items yet — add your first one to start receiving orders!</p>}</CardContent></Card><Dialog open={Boolean(draft)} onOpenChange={(open) => !open && setDraft(undefined)}><DialogContent><DialogHeader><DialogTitle>{draft?.id ? 'Edit menu item' : 'Add menu item'}</DialogTitle><DialogDescription>Add the details customers will see.</DialogDescription></DialogHeader>{draft && <div className="space-y-3"><Input value={draft.name} placeholder="Name" onChange={(e) => setDraft({ ...draft, name: e.target.value })} /><Textarea value={draft.description} placeholder="Description (optional)" onChange={(e) => setDraft({ ...draft, description: e.target.value })} /><Input value={draft.price} type="number" min="1" placeholder="Price (NGN)" onChange={(e) => setDraft({ ...draft, price: e.target.value })} /><Input value={draft.category} placeholder="Category (optional)" onChange={(e) => setDraft({ ...draft, category: e.target.value })} /><Input type="file" accept="image/*" onChange={(e) => setDraft({ ...draft, image: e.target.files?.[0] })} /><Button disabled={saving} onClick={() => void save()}>{saving ? 'Saving…' : 'Save item'}</Button></div>}</DialogContent></Dialog><Dialog open={Boolean(deleting)} onOpenChange={(open) => !open && setDeleting(undefined)}><DialogContent><DialogHeader><DialogTitle>Delete menu item?</DialogTitle><DialogDescription>This cannot be undone. Items with past orders will be kept to protect order history.</DialogDescription></DialogHeader><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setDeleting(undefined)}>Cancel</Button><Button variant="destructive" onClick={() => void remove()}>Delete</Button></div></DialogContent></Dialog></div> }
